BEGIN;

-- FA-1A records configuration consent only. There is no financial executor,
-- family promotion, balance, allocation, journal or effective policy head.
DO $$ DECLARE n text;r record;BEGIN
 FOREACH n IN ARRAY ARRAY['pactwoven_financial_verifier','pactwoven_financial_authorizer'] LOOP
  SELECT * INTO r FROM pg_roles WHERE rolname=n;
  IF NOT FOUND THEN EXECUTE format('CREATE ROLE %I NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS',n);
  ELSIF r.rolcanlogin OR r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication OR r.rolbypassrls
    OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=r.oid) THEN RAISE EXCEPTION 'Unsafe existing financial policy capability';END IF;
 END LOOP;
END $$;
GRANT USAGE ON SCHEMA pactwoven TO pactwoven_financial_verifier,pactwoven_financial_authorizer;

CREATE FUNCTION pactwoven.financial_policy_matches(v jsonb,s jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE k text;c jsonb;i int;t text:=jsonb_typeof(v);BEGIN
 IF v IS NULL OR s IS NULL OR s='false'::jsonb THEN RETURN false;END IF;
 IF s='true'::jsonb THEN RETURN true;END IF;
 IF s ? 'anyOf' THEN RETURN EXISTS(SELECT 1 FROM jsonb_array_elements(s->'anyOf') x WHERE pactwoven.financial_policy_matches(v,x));END IF;
 IF s ? 'oneOf' THEN RETURN (SELECT count(*)=1 FROM jsonb_array_elements(s->'oneOf') x WHERE pactwoven.financial_policy_matches(v,x));END IF;
 IF s ? 'const' AND v IS DISTINCT FROM s->'const' THEN RETURN false;END IF;
 IF s ? 'enum' AND NOT(s->'enum' @> jsonb_build_array(v)) THEN RETURN false;END IF;
 IF s ? 'type' AND t<>s->>'type' AND NOT(s->>'type'='integer' AND t='number' AND(v::text)::numeric=trunc((v::text)::numeric)) THEN RETURN false;END IF;
 IF t='object' THEN
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(s->'required','[]')) x WHERE NOT(v ? x)) THEN RETURN false;END IF;
  FOR k,c IN SELECT * FROM jsonb_each(v) LOOP
   IF NOT(coalesce(s->'properties','{}') ? k) THEN IF s->>'additionalProperties'='false' THEN RETURN false;END IF;
   ELSIF NOT pactwoven.financial_policy_matches(c,s->'properties'->k) THEN RETURN false;END IF;
  END LOOP;
 ELSIF t='array' THEN
  IF jsonb_array_length(v)<coalesce((s->>'minItems')::int,0) OR jsonb_array_length(v)>coalesce((s->>'maxItems')::int,1000) THEN RETURN false;END IF;
  FOR c,i IN SELECT value,ordinality::int-1 FROM jsonb_array_elements(v) WITH ORDINALITY LOOP
   IF jsonb_typeof(s->'items')='array' THEN
    IF i>=jsonb_array_length(s->'items') THEN IF s->>'additionalItems'='false' THEN RETURN false;END IF;
    ELSIF NOT pactwoven.financial_policy_matches(c,s->'items'->i) THEN RETURN false;END IF;
   ELSIF s ? 'items' AND NOT pactwoven.financial_policy_matches(c,s->'items') THEN RETURN false;END IF;
  END LOOP;
 ELSIF t='string' THEN
  IF length(v#>>'{}')<coalesce((s->>'minLength')::int,0) OR length(v#>>'{}')>coalesce((s->>'maxLength')::int,65536)
    OR(s ? 'pattern' AND(v#>>'{}') !~ (s->>'pattern')) THEN RETURN false;END IF;
  IF coalesce((s->>'pattern') LIKE '%d{4}%',false) THEN
   IF pactwoven.mandate_instant((v#>>'{}')::timestamptz) IS DISTINCT FROM(v#>>'{}') THEN RETURN false;END IF;
  END IF;
  IF (s->>'pattern') LIKE '%{8}%' AND(v#>>'{}')='00000000-0000-0000-0000-000000000000' THEN RETURN false;END IF;
  IF s->>'format'='uri' AND(v#>>'{}') !~ '^[A-Za-z][A-Za-z0-9+.-]*://[^[:space:]]+$' THEN RETURN false;END IF;
 ELSIF t='number' THEN
  IF(s ? 'minimum' AND(v::text)::numeric<(s->>'minimum')::numeric) OR(s ? 'maximum' AND(v::text)::numeric>(s->>'maximum')::numeric) THEN RETURN false;END IF;
 END IF;RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;END $$;

