^[A-Za-z0-9_-]+$"},"membershipVersion":{"type":"integer","minimum":1,"maximum":2147483647},"subject":{"type":"string","minLength":1,"maxLength":128,"pattern":"^[A-Za-z0-9_-]+$"},"externalMembershipId":{"type":"string","minLength":1,"maxLength":128,"pattern":"^[A-Za-z0-9_-]+$"},"sessionId":{"type":"string","minLength":1,"maxLength":256}},"required":["actorId","membershipVersion","subject","externalMembershipId","sessionId"],"additionalProperties":false},"organizationEpoch":{"type":"integer","minimum":0,"maximum":2147483647},"key":{"type":"string","minLength":16,"maxLength":128,"pattern":"^[A-Za-z0-9_-]+$"},"nonce":{"type":"string","pattern":"^[A-Za-z0-9_-]{42}[AEIMQUYcgkosw048]$"}},"required":["schemaVersion","purpose","environment","organizationId","proposal","control","proposer","approver","organizationEpoch","key","nonce"],"additionalProperties":false}$schema$::jsonb
ELSE NULL END $$;

CREATE FUNCTION pactwoven.financial_policy_hash(kind text,v jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT pactwoven.finance_hash(jsonb_build_object('namespace','pactwoven:financial-policy-'||kind||':v1','record',v))
$$;
CREATE FUNCTION pactwoven.financial_policy_ref(v jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('id',v->'id','version',v->'version','recordHash',pactwoven.financial_policy_hash(v->>'kind',v))
$$;
CREATE FUNCTION pactwoven.financial_policy_command_hash(a text,v jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT pactwoven.finance_hash(jsonb_build_object('namespace','pactwoven:financial-policy-command:v1','actorId',a,'command',v))
$$;
CREATE FUNCTION pactwoven.financial_policy_text_hash(v text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT pactwoven.finance_hash(jsonb_build_object('namespace','pactwoven:financial-policy-text:v1','text',v))
$$;
CREATE FUNCTION pactwoven.financial_budget_account_id(e text,o text,a text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT pactwoven.finance_hash(jsonb_build_object('namespace','pactwoven:financial-budget-account:v1','environment',e,'organizationId',o,'assetKey',a,'category','supplier_principal'))
$$;
CREATE FUNCTION pactwoven.financial_budget_period_id(a text,s text,e text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT pactwoven.finance_hash(jsonb_build_object('namespace','pactwoven:financial-budget-period:v1','budgetAccountId',a,'startsAt',s,'endsAt',e))
$$;
CREATE FUNCTION pactwoven.financial_policy_sorted(v jsonb,field text DEFAULT NULL) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT NOT EXISTS(SELECT 1 FROM(SELECT CASE WHEN field IS NULL THEN value#>>'{}' ELSE value->>field END AS val,
  lag(CASE WHEN field IS NULL THEN value#>>'{}' ELSE value->>field END) OVER(ORDER BY ordinality) AS prev FROM jsonb_array_elements(v) WITH ORDINALITY)x WHERE prev COLLATE "C">=val COLLATE "C")
$$;
CREATE FUNCTION pactwoven.financial_policy_valid(k text,v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE b jsonb;x jsonb;d jsonb;BEGIN
 IF NOT pactwoven.financial_policy_matches(v,pactwoven.financial_policy_schema(k)) OR octet_length(v::text)>180000 THEN RETURN false;END IF;
 IF k='bundle' THEN
  IF NOT pactwoven.financial_policy_sorted(v->'documents','id') OR jsonb_array_length(v->'documents')<>2
   OR NOT(v->'documents' @> '[{"purpose":"budget_policy"}]') OR NOT(v->'documents' @> '[{"purpose":"approval_policy"}]')
   OR NOT pactwoven.financial_policy_sorted(v#>'{approval,requesterRoles}') OR NOT pactwoven.financial_policy_sorted(v#>'{approval,approverRoles}')
   OR NOT pactwoven.financial_policy_sorted(v#>'{approval,actionSiteIds}') OR v#>>'{period,startsAt}'>=v#>>'{period,endsAt}'
   OR(v#>>'{limits,perOperation}')::numeric>(v#>>'{limits,perResponsibility}')::numeric OR(v#>>'{limits,perResponsibility}')::numeric>(v#>>'{limits,perPeriod}')::numeric
   OR(v#>>'{limits,perPeriod}')::numeric>18446744073709551615 OR(v#>>'{approval,thresholdBaseUnits}')::numeric>(v#>>'{limits,perOperation}')::numeric
   OR v#>>'{period,id}'<>pactwoven.financial_budget_period_id(v->>'budgetAccountId',v#>>'{period,startsAt}',v#>>'{period,endsAt}') THEN RETURN false;END IF;
 ELSIF k='draft' THEN
  IF v->>'startsAt'>=v->>'expiresAt' OR NOT pactwoven.financial_policy_sorted(v->'documents','id') OR jsonb_array_length(v->'documents')<>1
   OR v#>>'{documents,0,purpose}'<>'financial_mandate' OR v#>>'{scope,site,id}'<>v#>>'{scope,authority,responsibility,siteId}'
   OR(v->'account'<>'null'::jsonb AND v->'asset'='null'::jsonb) OR(v->'governance'<>'null'::jsonb AND v->'asset'='null'::jsonb)
   OR(v#>>'{scope,authority,family}'='none') IS DISTINCT FROM(v#>'{scope,authority,legacyHead}'='null'::jsonb)
   OR v#>>'{scope,authorityHash}'<>pactwoven.finance_hash(jsonb_build_object('namespace','pactwoven:financial-authority-fence:v1','record',v#>'{scope,authority}')) THEN RETURN false;END IF;
  IF v->'trust'<>'null'::jsonb THEN
   IF v->'asset'='null'::jsonb OR v->'account'='null'::jsonb OR v#>>'{trust,asset,key}'<>v#>>'{asset,key}' OR v#>>'{trust,account,key}'<>v#>>'{account,key}'
    OR NOT pactwoven.financial_policy_sorted(v#>'{trust,sources}','id') OR EXISTS(SELECT 1 FROM jsonb_array_elements(v#>'{trust,sources}')x WHERE x#>>'{binding,accountKey}'<>v#>>'{account,key}') THEN RETURN false;END IF;
  END IF;
 ELSIF k IN('record','command') THEN
  IF v->>'kind' IN('document','save_document') THEN
   IF length(v->>'text')>20000 OR btrim(v->>'text')='' OR normalize(v->>'text',NFC)<>v->>'text'
    OR(v->>'text')~'[\x01-\x08\x0b\x0c\x0e-\x1f\x7f\r]' THEN RETURN false;END IF;
   IF k='record' AND v->>'contentHash'<>pactwoven.financial_policy_text_hash(v->>'text') THEN RETURN false;END IF;
  ELSIF v->>'kind' IN('draft','save_draft') THEN
   IF NOT pactwoven.financial_policy_valid('draft',v->'draft') OR v#>>'{draft,scope,authority,environment}'<>v->>'environment'
    OR v#>>'{draft,scope,authority,organizationId}'<>v->>'organizationId' OR v#>>'{draft,scope,authority,responsibility,id}'<>v->>'responsibilityId'
    OR(v#>'{draft,trust}'<>'null'::jsonb AND(v#>>'{draft,trust,environment}'<>v->>'environment' OR v#>>'{draft,trust,organizationId}'<>v->>'organizationId')) THEN RETURN false;END IF;
  ELSIF v->>'kind' IN('governance','propose_governance') THEN
   IF NOT pactwoven.financial_policy_valid('bundle',v->'bundle') OR v#>>'{bundle,budgetAccountId}'<>pactwoven.financial_budget_account_id(v->>'environment',v->>'organizationId',v#>>'{bundle,asset,key}')
    OR v#>>'{expectedControl,budgetAccountId}'<>v#>>'{bundle,budgetAccountId}' THEN RETURN false;END IF;
  END IF;
  IF v ? 'expectedControl' AND (((v#>>'{expectedControl,generation}')::int=0) IS DISTINCT FROM(v#>'{expectedControl,accepted}'='null'::jsonb)) THEN RETURN false;END IF;
  IF k='record' THEN
   IF((v->>'version')::int=1) IS DISTINCT FROM(v->'predecessor'='null'::jsonb) OR((v->>'version')::int>1 AND(v#>>'{predecessor,id}'<>v->>'id' OR(v#>>'{predecessor,version}')::int+1<>(v->>'version')::int)) THEN RETURN false;END IF;
   IF v->>'kind'='governance' THEN
    IF(v->>'state'='OPEN') IS DISTINCT FROM(v->'decision'='null'::jsonb) OR(v->>'state'='ACCEPTED' AND(v#>'{decision,mfaEvidence}'='null'::jsonb OR v#>'{decision,intentHash}'='null'::jsonb OR v#>'{decision,requestHash}'='null'::jsonb))
     OR(v->>'state'='REJECTED' AND(v#>'{decision,mfaEvidence}'<>'null'::jsonb OR v#>'{decision,intentHash}'<>'null'::jsonb OR v#>'{decision,requestHash}'<>'null'::jsonb)) THEN RETURN false;END IF;
   END IF;
  END IF;
 END IF;RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;END $$;
CREATE FUNCTION pactwoven.financial_policy_require(k text,v jsonb) RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
BEGIN IF NOT pactwoven.financial_policy_valid(k,v) THEN RAISE EXCEPTION USING ERRCODE='FP004',MESSAGE='Exact supported policy input required';END IF;END $$;

CREATE TABLE pactwoven.financial_policy_principals(
 principal_oid oid NOT NULL,principal_name text NOT NULL,environment text NOT NULL,organization_id text NOT NULL,
 capability text NOT NULL CHECK(capability IN('authorizer','verifier')),version integer NOT NULL CHECK(version>0),active boolean NOT NULL,expires_at timestamptz NOT NULL,
 PRIMARY KEY(principal_oid,environment,organization_id,version),FOREIGN KEY(environment,organization_id) REFERENCES pactwoven.organizations(environment,id));
CREATE TABLE pactwoven.financial_policy_evidence(
 id uuid PRIMARY KEY,environment text NOT NULL,organization_id text NOT NULL,kind text NOT NULL,body jsonb NOT NULL,
 hash text GENERATED ALWAYS AS(pactwoven.financial_policy_hash('evidence',body)) STORED,
 principal_oid oid NOT NULL,principal_name text NOT NULL,principal_version integer NOT NULL CHECK(principal_version>0),
 CHECK(pactwoven.financial_policy_valid('evidence',body) AND body->>'id'=id::text AND body->>'environment'=environment AND body->>'organizationId'=organization_id AND body->>'kind'=kind));
CREATE TABLE pactwoven.financial_policy_operations(
 id uuid PRIMARY KEY,environment text NOT NULL,organization_id text NOT NULL,actor_id text NOT NULL,responsibility_id text,kind text NOT NULL,key text NOT NULL,
 command_hash text NOT NULL,command jsonb NOT NULL,result jsonb NOT NULL,UNIQUE(environment,organization_id,actor_id,kind,key));
CREATE TABLE pactwoven.financial_policy_records(
 environment text NOT NULL,organization_id text NOT NULL,id text NOT NULL,version integer NOT NULL CHECK(version>0),kind text NOT NULL,responsibility_id text,
 body jsonb NOT NULL CHECK(pactwoven.financial_policy_valid('record',body)),hash text GENERATED ALWAYS AS(pactwoven.financial_policy_hash(kind,body)) STORED,
 operation_id uuid NOT NULL UNIQUE REFERENCES pactwoven.financial_policy_operations(id) DEFERRABLE INITIALLY DEFERRED,
 PRIMARY KEY(environment,organization_id,id,version),FOREIGN KEY(environment,organization_id) REFERENCES pactwoven.organizations(environment,id),
 CHECK(body->>'environment'=environment AND body->>'organizationId'=organization_id AND body->>'id'=id AND(body->>'version')::int=version
 AND body->>'kind'=kind AND(body->>'responsibilityId') IS NOT DISTINCT FROM responsibility_id AND body->>'operationId'=operation_id::text));
CREATE TABLE pactwoven.financial_policy_audit(operation_id uuid PRIMARY KEY REFERENCES pactwoven.financial_policy_operations(id) DEFERRABLE INITIALLY DEFERRED,body jsonb NOT NULL);
CREATE TABLE pactwoven.financial_policy_outbox(operation_id uuid PRIMARY KEY REFERENCES pactwoven.financial_policy_operations(id) DEFERRABLE INITIALLY DEFERRED,body jsonb NOT NULL);
CREATE TABLE pactwoven.financial_policy_evidence_uses(evidence_id uuid PRIMARY KEY REFERENCES pactwoven.financial_policy_evidence(id),operation_id uuid NOT NULL UNIQUE REFERENCES pactwoven.financial_policy_operations(id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE pactwoven.financial_budget_accounts(
 id text PRIMARY KEY,environment text NOT NULL,organization_id text NOT NULL,asset_key text NOT NULL REFERENCES pactwoven.finance_physical_assets(asset_key),
 category text NOT NULL CHECK(category='supplier_principal'),operation_id uuid NOT NULL REFERENCES pactwoven.financial_policy_operations(id) DEFERRABLE INITIALLY DEFERRED,
 UNIQUE(environment,organization_id,asset_key,category),FOREIGN KEY(environment,organization_id) REFERENCES pactwoven.organizations(environment,id),
 CHECK(id=pactwoven.financial_budget_account_id(environment,organization_id,asset_key)));
CREATE TABLE pactwoven.financial_budget_periods(
 id text PRIMARY KEY,budget_account_id text NOT NULL REFERENCES pactwoven.financial_budget_accounts(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,
 operation_id uuid NOT NULL REFERENCES pactwoven.financial_policy_operations(id) DEFERRABLE INITIALLY DEFERRED,
 CHECK(starts_at<ends_at AND id=pactwoven.financial_budget_period_id(budget_account_id,pactwoven.mandate_instant(starts_at),pactwoven.mandate_instant(ends_at))),
 UNIQUE(budget_account_id,starts_at,ends_at));
CREATE TABLE pactwoven.financial_governance_controls(
 budget_account_id text NOT NULL REFERENCES pactwoven.financial_budget_accounts(id),generation integer NOT NULL CHECK(generation>0),
 environment text NOT NULL,organization_id text NOT NULL,record_id text NOT NULL,record_version integer NOT NULL,record_hash text NOT NULL,
 operation_id uuid NOT NULL UNIQUE REFERENCES pactwoven.financial_policy_operations(id) DEFERRABLE INITIALLY DEFERRED,
 PRIMARY KEY(budget_account_id,generation),FOREIGN KEY(environment,organization_id,record_id,record_version) REFERENCES pactwoven.financial_policy_records(environment,organization_id,id,version) DEFERRABLE INITIALLY DEFERRED);

CREATE FUNCTION pactwoven.financial_policy_role_safe(who oid,cap text) RETURNS boolean LANGUAGE sql VOLATILE SET search_path=pg_catalog AS $$
 WITH RECURSIVE reachable(oid) AS(SELECT who UNION SELECT m.roleid FROM pg_auth_members m JOIN reachable x ON x.oid=m.member),
 expected AS(SELECT to_regprocedure(name) AS oid FROM unnest(CASE cap WHEN 'verifier' THEN ARRAY['pactwoven.financial_policy_attest(jsonb)']
  WHEN 'authorizer' THEN ARRAY['pactwoven.financial_policy_command(uuid,jsonb)','pactwoven.financial_policy_read(uuid,jsonb)','pactwoven.financial_policy_list(uuid,jsonb)','pactwoven.financial_policy_recover(uuid,jsonb)'] ELSE ARRAY[]::text[] END) name),
 relations AS(SELECT c.* FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='pactwoven' AND c.relkind IN('r','p','v','m','f','S')),
 routines AS(SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='pactwoven' OR(p.prosecdef AND n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema'))
 SELECT cap IN('authorizer','verifier') AND coalesce(pactwoven.custody_system_privileges_safe(who),false)
  AND EXISTS(SELECT 1 FROM pg_roles WHERE oid=who AND rolcanlogin) AND pg_has_role(who,'pactwoven_financial_'||cap,'USAGE')
  AND NOT EXISTS(SELECT 1 FROM reachable x JOIN pg_roles r ON r.oid=x.oid WHERE r.rolsuper OR r.rolbypassrls OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication
   OR r.rolname IN('pactwoven_runtime','pactwoven_provisioner','pactwoven_access_provisioner','pactwoven_mandate_writer','pactwoven_finance_observer','pactwoven_custody_setup_writer','pactwoven_custody_setup_verifier',
     CASE cap WHEN 'authorizer' THEN 'pactwoven_financial_verifier' ELSE 'pactwoven_financial_authorizer' END))
  AND NOT EXISTS(SELECT 1 FROM reachable r JOIN pg_database d ON d.datdba=r.oid WHERE d.datname=current_database())
  AND NOT EXISTS(SELECT 1 FROM reachable r WHERE pg_has_role(r.oid,'pg_database_owner','USAGE') OR has_database_privilege(r.oid,current_database(),'CREATE'))
  AND NOT EXISTS(SELECT 1 FROM reachable r CROSS JOIN pg_namespace n WHERE n.nspname IN('pactwoven','public') AND(n.nspowner=r.oid OR pg_has_role(r.oid,n.nspowner,'USAGE') OR has_schema_privilege(r.oid,n.oid,'CREATE')))
  AND NOT EXISTS(SELECT 1 FROM reachable r CROSS JOIN relations t WHERE t.relowner=r.oid OR(t.relkind='S' AND has_sequence_privilege(r.oid,t.oid,'USAGE,SELECT,UPDATE'))
    OR(t.relkind<>'S' AND(has_table_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') OR has_any_column_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,REFERENCES'))))
  AND NOT EXISTS(SELECT 1 FROM reachable r CROSS JOIN routines f WHERE f.proowner=r.oid OR(has_function_privilege(r.oid,f.oid,'EXECUTE') AND f.oid NOT IN(SELECT oid FROM expected WHERE oid IS NOT NULL)))
  AND NOT EXISTS(SELECT 1 FROM expected e LEFT JOIN routines f ON f.oid=e.oid WHERE f.oid IS NULL OR NOT f.prosecdef
    OR f.proowner<>(SELECT nspowner FROM pg_namespace WHERE nspname='pactwoven') OR NOT(coalesce(f.proconfig,ARRAY[]::text[]) @> ARRAY['search_path=pg_catalog']) OR NOT has_function_privilege(who,f.oid,'EXECUTE'))
$$;
CREATE FUNCTION pactwoven.financial_policy_principal(e text,o text,cap text) RETURNS oid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r record;p record;BEGIN
 SELECT * INTO r FROM pg_roles WHERE rolname=SESSION_USER;
 IF current_setting('role')<>'none' OR NOT coalesce(pactwoven.financial_policy_role_safe(r.oid,cap),false) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Dedicated authenticated policy principal required';END IF;
 SELECT * INTO p FROM pactwoven.financial_policy_principals WHERE principal_oid=r.oid AND environment=e AND organization_id=o ORDER BY version DESC LIMIT 1;
 IF p.principal_name IS DISTINCT FROM r.rolname OR p.capability IS DISTINCT FROM cap OR NOT coalesce(p.active,false) OR p.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Current policy principal binding required';END IF;RETURN r.oid;
END $$;
CREATE FUNCTION pactwoven.financial_policy_evidence_current(eid uuid) RETURNS boolean LANGUAGE sql VOLATILE SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM pactwoven.financial_policy_evidence e JOIN pg_roles r ON r.oid=e.principal_oid AND r.rolname=e.principal_name
 JOIN LATERAL(SELECT * FROM pactwoven.financial_policy_principals p WHERE p.principal_oid=e.principal_oid AND p.environment=e.environment AND p.organization_id=e.organization_id ORDER BY version DESC LIMIT 1)p ON true
 WHERE e.id=eid AND p.principal_name=r.rolname AND p.capability='verifier' AND p.version=e.principal_version AND p.active AND p.expires_at>clock_timestamp()
 AND coalesce(pactwoven.financial_policy_role_safe(r.oid,'verifier'),false))
$$;
CREATE FUNCTION pactwoven.financial_policy_actor_current(v jsonb) RETURNS boolean LANGUAGE sql VOLATILE SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM pactwoven.organizations o JOIN pactwoven.memberships m ON m.environment=o.environment AND m.organization_id=o.id
 WHERE o.environment=v->>'environment' AND o.id=v->>'organizationId' AND o.status='active' AND o.external_organization_id=v->>'externalOrganizationId'
 AND m.actor_id=v#>>'{actor,actorId}' AND m.status='active' AND m.roles&&ARRAY['owner','finance','operations']::text[]
 AND m.row_version=(v#>>'{actor,membershipVersion}')::int AND m.external_subject=v#>>'{actor,subject}' AND m.external_membership_id=v#>>'{actor,externalMembershipId}'
 AND(m.expires_at IS NULL OR m.expires_at>clock_timestamp()) AND(m.grant_basis<>'clerk_admin_bootstrap' OR v->>'externalRole'='org:admin')
 AND NOT EXISTS(SELECT 1 FROM pactwoven.session_revocations WHERE environment=o.environment AND session_id=v#>>'{actor,sessionId}')
 AND(v->>'observedAt')::timestamptz<=clock_timestamp() AND(v->>'observedAt')::timestamptz>=clock_timestamp()-interval '20 seconds'
 AND(v->>'expiresAt')::timestamptz>clock_timestamp() AND(v->>'expiresAt')::timestamptz<=(v->>'observedAt')::timestamptz+interval '5 minutes'
 AND(v->>'expiresAt')::timestamptz<=(v->>'sessionExpiresAt')::timestamptz AND(v->>'tokenIssuedAt')::timestamptz<=(v->>'observedAt')::timestamptz)
$$;
CREATE FUNCTION pactwoven.financial_policy_context(eid uuid,e text,o text,rid text,cap text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='3s' AS $$
DECLARE v jsonb;org pactwoven.organizations%ROWTYPE;m pactwoven.memberships%ROWTYPE;r pactwoven.responsibilities%ROWTYPE;BEGIN
 PERFORM pactwoven.financial_require_read_committed();
 SELECT body INTO v FROM pactwoven.financial_policy_evidence WHERE id=eid AND kind='identity' AND environment=e AND organization_id=o;
 IF v IS NULL THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Private identity observation required';END IF;
 SELECT * INTO org FROM pactwoven.organizations WHERE environment=e AND id=o FOR UPDATE;
 LOCK TABLE pactwoven.session_revocations IN SHARE MODE;
 PERFORM actor_id FROM pactwoven.memberships WHERE environment=e AND organization_id=o ORDER BY actor_id COLLATE "C" FOR SHARE;
 IF NOT pactwoven.financial_policy_actor_current(v) OR NOT pactwoven.financial_policy_evidence_current(eid) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Current scoped policy identity required';END IF;
 SELECT * INTO m FROM pactwoven.memberships WHERE environment=e AND organization_id=o AND actor_id=v#>>'{actor,actorId}';
 IF rid IS NOT NULL THEN SELECT * INTO r FROM pactwoven.responsibilities WHERE environment=e AND organization_id=o AND id=rid FOR SHARE;END IF;
 PERFORM id FROM pactwoven.sites WHERE environment=e AND organization_id=o ORDER BY id COLLATE "C" FOR SHARE;
 IF rid IS NOT NULL THEN
  IF r.id IS NULL OR NOT EXISTS(SELECT 1 FROM pactwoven.site_memberships WHERE environment=e AND organization_id=o AND actor_id=m.actor_id AND site_id=r.site_id)
   OR NOT EXISTS(SELECT 1 FROM pactwoven.member_action_sites WHERE environment=e AND organization_id=o AND actor_id=m.actor_id AND site_id=r.site_id) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Explicit policy site grants required';END IF;
  PERFORM responsibility_id FROM pactwoven.financial_authority_fences WHERE environment=e AND organization_id=o AND responsibility_id=rid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Canonical responsibility scope unavailable';END IF;
 END IF;
 PERFORM pactwoven.financial_policy_principal(e,o,cap);
 IF NOT pactwoven.financial_policy_actor_current(v) OR NOT pactwoven.financial_policy_evidence_current(eid) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Policy identity expired while waiting';END IF;
 RETURN jsonb_build_object('identity',v,'roles',to_jsonb(m.roles),'organizationEpoch',org.authority_epoch,'responsibility',CASE WHEN rid IS NULL THEN NULL ELSE pactwoven.mandate_responsibility_body(r) END);
END $$;
CREATE FUNCTION pactwoven.financial_policy_control(a text) RETURNS jsonb LANGUAGE sql VOLATILE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('budgetAccountId',a,'generation',coalesce(c.generation,0),'accepted',CASE WHEN c.generation IS NULL THEN NULL
 ELSE jsonb_build_object('id',c.record_id,'version',c.record_version,'recordHash',c.record_hash) END)
 FROM(SELECT 1)x LEFT JOIN LATERAL(SELECT * FROM pactwoven.financial_governance_controls WHERE budget_account_id=a ORDER BY generation DESC LIMIT 1)c ON true
$$;
CREATE FUNCTION pactwoven.financial_policy_intent(p jsonb,a jsonb,k text,epoch integer) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('schemaVersion',1,'purpose','financial_policy_authorization','environment',p->'environment','organizationId',p->'organizationId',
  'proposal',pactwoven.financial_policy_ref(p),'control',p->'expectedControl','proposer',p->'proposer','approver',a,'organizationEpoch',epoch,'key',k,'nonce',p->'decisionNonce')
$$;
CREATE FUNCTION pactwoven.financial_policy_attest(v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='3s' AS $$
DECLARE who oid;org pactwoven.organizations%ROWTYPE;p jsonb;old jsonb;i jsonb;h text;BEGIN
 PERFORM pactwoven.financial_require_read_committed();PERFORM pactwoven.financial_policy_require('evidence',v);
 SELECT * INTO org FROM pactwoven.organizations WHERE environment=v->>'environment' AND id=v->>'organizationId' FOR UPDATE;
 LOCK TABLE pactwoven.session_revocations IN SHARE MODE;
 PERFORM actor_id FROM pactwoven.memberships WHERE environment=org.environment AND organization_id=org.id ORDER BY actor_id COLLATE "C" FOR SHARE;
 who:=pactwoven.financial_policy_principal(org.environment,org.id,'verifier');
 IF NOT pactwoven.financial_policy_actor_current(v) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Current verified policy observation required';END IF;
 SELECT body INTO old FROM pactwoven.financial_policy_evidence WHERE id=(v->>'id')::uuid;
 IF old IS NOT NULL THEN
  IF old<>v THEN RAISE EXCEPTION USING ERRCODE='FP005',MESSAGE='Immutable policy evidence identity conflict';END IF;
  IF NOT pactwoven.financial_policy_evidence_current((v->>'id')::uuid) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Original policy verifier binding changed';END IF;
  RETURN jsonb_build_object('id',v->'id','version',1,'recordHash',pactwoven.financial_policy_hash('evidence',v));
 END IF;
 IF v->>'kind'='mfa' THEN
  SELECT body INTO p FROM pactwoven.financial_policy_records WHERE environment=org.environment AND organization_id=org.id AND id=v#>>'{intent,proposal,id}' ORDER BY version DESC LIMIT 1;
  i:=pactwoven.financial_policy_intent(p,v->'actor',v#>>'{intent,key}',org.authority_epoch);
  IF p IS NULL OR p->>'kind'<>'governance' OR p->>'state'<>'OPEN' OR v->'intent' IS DISTINCT FROM i
   OR p->'expectedControl' IS DISTINCT FROM pactwoven.financial_policy_control(p#>>'{bundle,budgetAccountId}')
   OR p#>>'{proposer,actorId}'=v#>>'{actor,actorId}' OR p#>>'{proposer,subject}'=v#>>'{actor,subject}' OR p#>>'{proposer,externalMembershipId}'=v#>>'{actor,externalMembershipId}'
   OR NOT EXISTS(SELECT 1 FROM pactwoven.memberships WHERE environment=org.environment AND organization_id=org.id AND actor_id=v#>>'{actor,actorId}' AND roles&&ARRAY['owner','finance']::text[])
   OR(v->>'verifiedAt')::timestamptz IS DISTINCT FROM(v->>'tokenIssuedAt')::timestamptz-(greatest((v->>'firstFactorAgeMinutes')::int,(v->>'secondFactorAgeMinutes')::int)+1)*interval '1 minute'
   OR(v->>'expiresAt')::timestamptz>(v->>'verifiedAt')::timestamptz+(p#>>'{bundle,approval,maximumAuthenticationAgeSeconds}')::int*interval '1 second'
   OR(v->>'expiresAt')::timestamptz>(v->>'observedAt')::timestamptz+(p#>>'{bundle,approval,maximumApprovalAgeSeconds}')::int*interval '1 second'
   OR(v->>'expiresAt')::timestamptz>(p->>'expiresAt')::timestamptz OR v->>'intentHash'<>pactwoven.finance_hash(i)
   OR v->>'requestHash'<>pactwoven.finance_hash(jsonb_build_object('schemaVersion',1,'purpose','financial_policy_authorization','request',jsonb_build_object('nonce',i->'nonce','key',i->'key','intent',i)))
  THEN RAISE EXCEPTION USING ERRCODE='FP004',MESSAGE='Exact independent fresh policy MFA required';END IF;
 END IF;
 h:=pactwoven.financial_policy_hash('evidence',v);
 INSERT INTO pactwoven.financial_policy_evidence(id,environment,organization_id,kind,body,principal_oid,principal_name,principal_version)
 SELECT(v->>'id')::uuid,org.environment,org.id,v->>'kind',v,who,SESSION_USER,version FROM pactwoven.financial_policy_principals WHERE principal_oid=who AND environment=org.environment AND organization_id=org.id ORDER BY version DESC LIMIT 1;
 RETURN jsonb_build_object('id',v->'id','version',1,'recordHash',h);
END $$;

CREATE FUNCTION pactwoven.financial_policy_documents(e text,o text,rid text,refs jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x jsonb;d jsonb;BEGIN
 FOR x IN SELECT * FROM jsonb_array_elements(refs) LOOP
  SELECT body INTO d FROM pactwoven.financial_policy_records WHERE environment=e AND organization_id=o AND id=x->>'id' ORDER BY version DESC LIMIT 1;
  IF d IS NULL OR d->>'kind'<>'document' OR(d->>'responsibilityId') IS DISTINCT FROM rid OR d->>'purpose'<>x->>'purpose'
   OR pactwoven.financial_policy_ref(d) IS DISTINCT FROM(x-'purpose') THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Exact current full policy document required';END IF;
 END LOOP;
END $$;
CREATE FUNCTION pactwoven.financial_policy_asset(pin jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c pactwoven.finance_asset_controls%ROWTYPE;f pactwoven.financial_asset_fences%ROWTYPE;v jsonb;BEGIN
 PERFORM asset_key FROM pactwoven.finance_physical_assets WHERE asset_key=pin->>'key' FOR SHARE;
 SELECT * INTO c FROM pactwoven.finance_asset_controls WHERE asset_key=pin->>'key' FOR SHARE;
 SELECT * INTO f FROM pactwoven.financial_asset_fences WHERE asset_key=pin->>'key' FOR SHARE;
 SELECT to_jsonb(x) INTO v FROM pactwoven.finance_asset_versions x WHERE asset_key=c.asset_key AND version=c.current_version;
 IF c.asset_key IS NULL OR NOT c.accepts_observations OR c.revoked_at IS NOT NULL OR c.current_version IS DISTINCT FROM(pin->>'version')::int
  OR f.generation IS DISTINCT FROM(pin->>'financialUseEpoch')::int OR pactwoven.finance_hash(v) IS DISTINCT FROM pin->>'recordHash' THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Exact registered physical asset required';END IF;
END $$;
CREATE FUNCTION pactwoven.financial_policy_account(e text,o text,asset jsonb,pin jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c pactwoven.finance_account_controls%ROWTYPE;f pactwoven.financial_account_fences%ROWTYPE;v jsonb;BEGIN
 PERFORM account_key FROM pactwoven.finance_physical_accounts WHERE account_key=pin->>'key' AND environment=e AND organization_id=o FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Exact scoped physical account required';END IF;
 SELECT * INTO c FROM pactwoven.finance_account_controls WHERE account_key=pin->>'key' FOR SHARE;
 SELECT * INTO f FROM pactwoven.financial_account_fences WHERE account_key=pin->>'key' FOR SHARE;
 SELECT to_jsonb(x) INTO v FROM pactwoven.finance_account_versions x WHERE account_key=c.account_key AND version=c.current_version;
 IF c.account_key IS NULL OR NOT c.accepts_observations OR c.revoked_at IS NOT NULL OR c.current_version IS DISTINCT FROM(pin->>'version')::int
  OR f.generation IS DISTINCT FROM(pin->>'financialUseEpoch')::int OR pactwoven.finance_hash(v) IS DISTINCT FROM pin->>'recordHash' OR v->>'asset_key' IS DISTINCT FROM asset->>'key'
 THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Exact registered physical account required';END IF;
END $$;
CREATE FUNCTION pactwoven.financial_policy_site_grants(e text,o text,a text,ids jsonb,active_required boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE s text;BEGIN
 FOR s IN SELECT * FROM jsonb_array_elements_text(ids) LOOP
  IF NOT EXISTS(SELECT 1 FROM pactwoven.site_memberships WHERE environment=e AND organization_id=o AND actor_id=a AND site_id=s)
   OR NOT EXISTS(SELECT 1 FROM pactwoven.member_action_sites WHERE environment=e AND organization_id=o AND actor_id=a AND site_id=s)
   OR NOT EXISTS(SELECT 1 FROM pactwoven.financial_site_fences WHERE environment=e AND organization_id=o AND site_id=s AND(NOT active_required OR active)) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Current explicit policy action-site grants required';END IF;
 END LOOP;
END $$;

CREATE FUNCTION pactwoven.financial_policy_command(eid uuid,v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='3s' AS $$
#variable_conflict use_column
DECLARE c jsonb;p jsonb;body jsonb;old jsonb;result jsonb;common jsonb;bundle jsonb;current_control jsonb;d jsonb;prop jsonb;mf jsonb;intent jsonb;dec jsonb;
 e text:=v->>'environment';o text:=v->>'organizationId';rid text:=v->>'responsibilityId';action_kind text:=v->>'kind';a jsonb;op uuid:=gen_random_uuid();h text;ver int;at_time timestamptz;
 f pactwoven.financial_authority_fences%ROWTYPE;s pactwoven.financial_site_fences%ROWTYPE;accepted jsonb;
BEGIN
 PERFORM pactwoven.financial_policy_require('command',v);c:=pactwoven.financial_policy_context(eid,e,o,rid,'authorizer');a:=c#>'{identity,actor}';h:=pactwoven.financial_policy_command_hash(a->>'actorId',v);
 SELECT x.result INTO old FROM pactwoven.financial_policy_operations x WHERE environment=e AND organization_id=o AND actor_id=a->>'actorId' AND x.kind=action_kind AND key=v->>'key';
 IF old IS NOT NULL THEN IF old->>'commandHash'<>h THEN RAISE EXCEPTION USING ERRCODE='FP005',MESSAGE='Original policy key conflict';END IF;RETURN old;END IF;
 IF v->'organizationEpoch' IS DISTINCT FROM c->'organizationEpoch' THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Organization authority changed';END IF;
 SELECT x.body INTO p FROM pactwoven.financial_policy_records x WHERE environment=e AND organization_id=o AND id=v->>'id' ORDER BY version DESC LIMIT 1 FOR UPDATE;
 IF p IS NULL THEN
  IF v->'previous'<>'null'::jsonb THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Unexpected policy predecessor';END IF;ver:=1;
 ELSE
  IF v->'previous' IS DISTINCT FROM pactwoven.financial_policy_ref(p) OR(p->>'responsibilityId') IS DISTINCT FROM rid OR(p->>'version')::int=2147483647 THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Exact current policy predecessor required';END IF;
  ver:=(p->>'version')::int+1;
 END IF;
 at_time:=clock_timestamp();
 common:=jsonb_build_object('schemaVersion',1,'environment',e,'organizationId',o,'id',v->'id','version',ver,'predecessor',v->'previous',
  'responsibilityId',v->'responsibilityId','actor',a,'identityEvidence',jsonb_build_object('id',c#>'{identity,id}','version',1,'recordHash',pactwoven.financial_policy_hash('evidence',c->'identity')),
  'organizationEpoch',c->'organizationEpoch','operationId',op,'createdAt',pactwoven.mandate_instant(at_time));
 IF action_kind='save_document' THEN
  IF(v->>'purpose'='financial_mandate') IS DISTINCT FROM(rid IS NOT NULL) OR(p IS NOT NULL AND(p->>'kind'<>'document' OR p->>'purpose'<>v->>'purpose' OR p#>>'{actor,actorId}'<>a->>'actorId'))
   OR(v->>'purpose'<>'financial_mandate' AND NOT(c->'roles' ? 'owner')) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Original policy author and purpose scope required';END IF;
  IF rid IS NOT NULL THEN PERFORM pactwoven.financial_policy_site_grants(e,o,a->>'actorId',jsonb_build_array(c#>'{responsibility,siteId}'),true);END IF;
  body:=common||jsonb_build_object('kind','document','purpose',v->'purpose','text',v->'text','contentHash',pactwoven.financial_policy_text_hash(v->>'text'));
 ELSIF action_kind IN('save_draft','withdraw_draft') THEN
  IF p IS NOT NULL AND(p->>'kind'<>'draft' OR p->>'state'<>'DRAFT' OR p#>>'{requester,actorId}'<>a->>'actorId' OR p#>>'{requester,subject}'<>a->>'subject') THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Original open policy draft required';END IF;
  IF action_kind='withdraw_draft' THEN
   IF p IS NULL THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Original draft required';END IF;
   body:=common||jsonb_build_object('kind','draft','state','WITHDRAWN','requester',p->'requester','draft',p->'draft');
  ELSE
   d:=v->'draft';SELECT * INTO f FROM pactwoven.financial_authority_fences WHERE environment=e AND organization_id=o AND responsibility_id=rid;
   SELECT * INTO s FROM pactwoven.financial_site_fences WHERE environment=e AND organization_id=o AND site_id=c#>>'{responsibility,siteId}';
   IF d#>'{scope,authority}' IS DISTINCT FROM pactwoven.financial_authority_snapshot(f) OR d#>>'{scope,authorityHash}' IS DISTINCT FROM pactwoven.financial_authority_fence_hash(f)
    OR d#>'{scope,site}' IS DISTINCT FROM jsonb_build_object('id',s.site_id,'generation',s.generation,'recordHash',s.record_hash) OR NOT coalesce(s.active,false)
    OR(d->>'expiresAt')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Current draft scope and expiry required';END IF;
   PERFORM pactwoven.financial_policy_documents(e,o,rid,d->'documents');
   IF d->'trust'<>'null'::jsonb THEN RAISE EXCEPTION USING ERRCODE='FP006',MESSAGE='Actual financial trust resolution is not installed';END IF;
   IF d->'asset'<>'null'::jsonb THEN PERFORM pactwoven.financial_policy_asset(d->'asset');END IF;
   IF d->'account'<>'null'::jsonb THEN PERFORM pactwoven.financial_policy_account(e,o,d->'asset',d->'account');END IF;
   IF d->'governance'<>'null'::jsonb THEN
    current_control:=pactwoven.financial_policy_control(d#>>'{governance,budgetAccountId}');
    SELECT x.body INTO accepted FROM pactwoven.financial_policy_records x WHERE environment=e AND organization_id=o AND id=d#>>'{governance,accepted,id}' AND version=(d#>>'{governance,accepted,version}')::int;
    IF d->'governance' IS DISTINCT FROM current_control OR accepted IS NULL OR accepted->>'state'<>'ACCEPTED' OR accepted->>'kind'<>'governance'
     OR accepted#>>'{bundle,asset,key}' IS DISTINCT FROM d#>>'{asset,key}' OR(d->>'startsAt')::timestamptz<(accepted#>>'{bundle,period,startsAt}')::timestamptz
     OR(d->>'expiresAt')::timestamptz>(accepted#>>'{bundle,period,endsAt}')::timestamptz OR NOT(accepted#>'{bundle,approval,actionSiteIds}' ? s.site_id)
    THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Exact current governance and one fixed period required';END IF;
   END IF;
   body:=common||jsonb_build_object('kind','draft','state','DRAFT','requester',a,'draft',d);
  END IF;
 ELSE
  IF p IS NOT NULL AND(p->>'kind'<>'governance' OR p->>'state'<>'OPEN') THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Exact open governance proposal required';END IF;
  IF action_kind='propose_governance' THEN
   IF NOT(c->'roles' ? 'owner') OR(p IS NOT NULL AND(p#>>'{proposer,actorId}'<>a->>'actorId' OR p#>>'{proposer,subject}'<>a->>'subject')) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Current original owner proposal required';END IF;
   bundle:=v->'bundle';
   IF p IS NOT NULL AND p#>>'{bundle,budgetAccountId}'<>bundle->>'budgetAccountId' THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='A governance version cannot replace its stable budget identity';END IF;
   IF(v->>'expiresAt')::timestamptz<=clock_timestamp() OR(v->>'expiresAt')::timestamptz>(bundle#>>'{period,endsAt}')::timestamptz THEN RAISE EXCEPTION USING ERRCODE='FP003',MESSAGE='Current bounded governance proposal expiry required';END IF;
  ELSE
   IF p IS NULL OR NOT(c->'roles' ?| ARRAY['owner','finance']) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Current governance reviewer required';END IF;bundle:=p->'bundle';
  END IF;
  PERFORM pactwoven.financial_policy_asset(bundle->'asset');
  PERFORM pactwoven.financial_policy_documents(e,o,NULL,bundle->'documents');
  PERFORM pactwoven.financial_policy_site_grants(e,o,a->>'actorId',bundle#>'{approval,actionSiteIds}',action_kind<>'reject_governance');
  current_control:=pactwoven.financial_policy_control(bundle->>'budgetAccountId');
  IF v->'expectedControl' IS DISTINCT FROM current_control OR(action_kind<>'propose_governance' AND p->'expectedControl' IS DISTINCT FROM current_control) THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Governance configuration changed';END IF;
  IF action_kind='propose_governance' THEN
   INSERT INTO pactwoven.financial_budget_accounts(id,environment,organization_id,asset_key,category,operation_id)
    VALUES(bundle->>'budgetAccountId',e,o,bundle#>>'{asset,key}','supplier_principal',op) ON CONFLICT(id) DO NOTHING;
   IF EXISTS(SELECT 1 FROM pactwoven.financial_budget_periods WHERE budget_account_id=bundle->>'budgetAccountId' AND id<>bundle#>>'{period,id}'
    AND starts_at<(bundle#>>'{period,endsAt}')::timestamptz AND ends_at>(bundle#>>'{period,startsAt}')::timestamptz) THEN RAISE EXCEPTION USING ERRCODE='FP002',MESSAGE='Fixed budget periods cannot overlap or reset identity';END IF;
   INSERT INTO pactwoven.financial_budget_periods(id,budget_account_id,starts_at,ends_at,operation_id)
    VALUES(bundle#>>'{period,id}',bundle->>'budgetAccountId',(bundle#>>'{period,startsAt}')::timestamptz,(bundle#>>'{period,endsAt}')::timestamptz,op) ON CONFLICT(id) DO NOTHING;
   body:=common||jsonb_build_object('kind','governance','state','OPEN','proposer',a,'bundle',bundle,'expectedControl',current_control,'decisionNonce',pactwoven.custody_nonce(),'expiresAt',v->'expiresAt','decision',NULL);
  ELSE
   SELECT x.body INTO prop FROM pactwoven.financial_policy_evidence x WHERE x.id=(v->>'proposerEvidenceId')::uuid AND kind='identity' AND environment=e AND organization_id=o;
   IF prop IS NULL OR prop->'actor' IS DISTINCT FROM p->'proposer' OR NOT pactwoven.financial_policy_actor_current(prop) OR NOT pactwoven.financial_policy_evidence_current((prop->>'id')::uuid)
    OR NOT EXISTS(SELECT 1 FROM pactwoven.memberships WHERE environment=e AND organization_id=o AND actor_id=prop#>>'{actor,actorId}' AND 'owner'=ANY(roles))
   THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Current original owner observation required';END IF;
   PERFORM pactwoven.financial_policy_site_grants(e,o,prop#>>'{actor,actorId}',bundle#>'{approval,actionSiteIds}',action_kind<>'reject_governance');
   dec:=jsonb_build_object('proposerObservation',jsonb_build_object('id',prop->'id','version',1,'recordHash',pactwoven.financial_policy_hash('evidence',prop)),
    'approverObservation',jsonb_build_object('id',c#>'{identity,id}','version',1,'recordHash',pactwoven.financial_policy_hash('evidence',c->'identity')),'mfaEvidence',NULL,'intentHash',NULL,'requestHash',NULL);
   IF action_kind='accept_governance' THEN
    IF p#>>'{proposer,actorId}'=a->>'actorId' OR p#>>'{proposer,subject}'=a->>'subject' OR p#>>'{proposer,externalMembershipId}'=a->>'externalMembershipId'
     OR(v->>'nonce') IS DISTINCT FROM p->>'decisionNonce' OR(p->>'organizationEpoch')::int IS DISTINCT FROM(c->>'organizationEpoch')::int
     OR(current_control->>'generation')::int=2147483647 THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Independent exact policy consent required';END IF;
    IF(p->>'expiresAt')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='FP003',MESSAGE='Governance proposal expired';END IF;
    SELECT x.body INTO mf FROM pactwoven.financial_policy_evidence x WHERE x.id=(v->>'mfaEvidenceId')::uuid AND x.kind='mfa' AND environment=e AND organization_id=o;
    intent:=pactwoven.financial_policy_intent(p,a,v->>'key',(c->>'organizationEpoch')::int);
    IF mf IS NULL OR mf->'intent' IS DISTINCT FROM intent OR NOT pactwoven.financial_policy_actor_current(mf) OR NOT pactwoven.financial_policy_evidence_current((mf->>'id')::uuid)
     OR mf->'actor' IS DISTINCT FROM a OR mf->>'intentHash'<>pactwoven.finance_hash(intent)
     OR(clock_timestamp()>(mf->>'verifiedAt')::timestamptz+(bundle#>>'{approval,maximumAuthenticationAgeSeconds}')::int*interval '1 second')
     OR(clock_timestamp()>(mf->>'observedAt')::timestamptz+(bundle#>>'{approval,maximumApprovalAgeSeconds}')::int*interval '1 second')
     OR EXISTS(SELECT 1 FROM pactwoven.financial_policy_evidence_uses WHERE evidence_id=(mf->>'id')::uuid) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Exact fresh unused governance MFA required';END IF;
    dec:=dec||jsonb_build_object('mfaEvidence',jsonb_build_object('id',mf->'id','version',1,'recordHash',pactwoven.financial_policy_hash('evidence',mf)),'intentHash',mf->'intentHash','requestHash',mf->'requestHash');
   END IF;
   body:=common||jsonb_build_object('kind','governance','state',CASE action_kind WHEN 'accept_governance' THEN 'ACCEPTED' ELSE 'REJECTED' END,'proposer',p->'proposer',
    'bundle',bundle,'expectedControl',current_control,'decisionNonce',p->'decisionNonce','expiresAt',p->'expiresAt','decision',dec);
  END IF;
 END IF;
 -- Every waited-on reference and observation is checked before the immutable transition.
 IF NOT pactwoven.financial_policy_actor_current(c->'identity') OR NOT pactwoven.financial_policy_evidence_current(eid)
  OR(prop IS NOT NULL AND(NOT pactwoven.financial_policy_actor_current(prop) OR NOT pactwoven.financial_policy_evidence_current((prop->>'id')::uuid)))
  OR(mf IS NOT NULL AND(NOT pactwoven.financial_policy_actor_current(mf) OR NOT pactwoven.financial_policy_evidence_current((mf->>'id')::uuid))) THEN RAISE EXCEPTION USING ERRCODE='FP001',MESSAGE='Policy observation expired while waiting';END IF;
 PERFORM pactwoven.financial_policy_principal(e,o,'authorizer');
 IF action_kind IN('propose_governance','accept_governance') AND(body->>'expiresAt')::timestamptz<=clock_timestamp()
  OR action_kind='save_draft' AND(body#>>'{draft,expiresAt}')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='FP003',MESSAGE='Policy expired while waiting';END IF;
 body:=body||jsonb_build_object('createdAt',pactwoven.mandate_instant(clock_timestamp()));PERFORM pactwoven.financial_policy_require('record',body);
 result:=jsonb_build_object('schemaVersion',1,'id',op,'environment',e,'organizationId',o,'actorId',a->'actorId','responsibilityId',v->'responsibilityId','kind',action_kind,'key',v->'key',
  'commandHash',h,'target',pactwoven.financial_policy_ref(body),'body',body,'financialState',NULL,'effectiveAuthority',false);
 INSERT INTO pactwoven.financial_policy_operations VALUES(op,e,o,a->>'actorId',rid,action_kind,v->>'key',h,v,result);
 INSERT INTO pactwoven.financial_policy_records(environment,organization_id,id,version,kind,responsibility_id,body,operation_id) VALUES(e,o,v->>'id',ver,body->>'kind',rid,body,op);
 INSERT INTO pactwoven.financial_policy_audit VALUES(op,result-'body');INSERT INTO pactwoven.financial_policy_outbox VALUES(op,result-'body');
 IF action_kind='accept_governance' THEN
  INSERT INTO pactwoven.financial_policy_evidence_uses VALUES((mf->>'id')::uuid,op);
  INSERT INTO pactwoven.financial_governance_controls VALUES(bundle->>'budgetAccountId',(current_control->>'generation')::int+1,e,o,body->>'id',ver,pactwoven.financial_policy_hash('governance',body),op);
 END IF;
 RETURN result;
END $$;

CREATE FUNCTION pactwoven.financial_policy_projection(v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE current_version int;is_current boolean;state text;blockers jsonb:='[]';d jsonb;f pactwoven.financial_authority_fences%ROWTYPE;s pactwoven.financial_site_fences%ROWTYPE;BEGIN
 SELECT max(version) INTO current_version FROM pactwoven.financial_policy_records WHERE environment=v->>'environment' AND organization_id=v->>'organizationId' AND id=v->>'id';
 is_current:=current_version=(v->>'version')::int;
 IF v->>'kind'='governance' AND v->>'state'='OPEN' AND v->'expectedControl' IS DISTINCT FROM pactwoven.financial_policy_control(v#>>'{bundle,budgetAccountId}') THEN is_current:=false;END IF;
 state:=CASE WHEN NOT is_current THEN 'SUPERSEDED' WHEN v->>'kind'='document' THEN 'DOCUMENT'
  WHEN v->>'kind'='governance' AND v->>'state'='OPEN' AND(v->>'expiresAt')::timestamptz<=clock_timestamp() THEN 'EXPIRED' ELSE v->>'state' END;
 IF v->>'kind'='draft' THEN
  d:=v->'draft';blockers:='["TRUST_UNAVAILABLE","FINANCIAL_AUTHORITY_UNAVAILABLE"]';
  IF v->>'state'='WITHDRAWN' THEN blockers:=blockers||'"DRAFT_WITHDRAWN"'::jsonb;END IF;
  IF(d->>'expiresAt')::timestamptz<=clock_timestamp() THEN blockers:=blockers||'"DRAFT_EXPIRED"'::jsonb;IF state='DRAFT' THEN state:='EXPIRED';END IF;END IF;
  IF d->'asset'='null'::jsonb THEN blockers:=blockers||'"ASSET_MISSING"'::jsonb;
  ELSIF NOT EXISTS(SELECT 1 FROM pactwoven.finance_asset_controls c JOIN pactwoven.finance_asset_versions av ON av.asset_key=c.asset_key AND av.version=c.current_version
   JOIN pactwoven.financial_asset_fences af ON af.asset_key=c.asset_key WHERE c.asset_key=d#>>'{asset,key}' AND c.accepts_observations AND c.revoked_at IS NULL
   AND c.current_version=(d#>>'{asset,version}')::int AND af.generation=(d#>>'{asset,financialUseEpoch}')::int AND pactwoven.finance_hash(to_jsonb(av))=d#>>'{asset,recordHash}')
  THEN blockers:=blockers||'"ASSET_CHANGED"'::jsonb;END IF;
  IF d->'account'='null'::jsonb THEN blockers:=blockers||'"ACCOUNT_MISSING"'::jsonb;
  ELSIF NOT EXISTS(SELECT 1 FROM pactwoven.finance_physical_accounts pa JOIN pactwoven.finance_account_controls c USING(account_key)
   JOIN pactwoven.finance_account_versions av ON av.account_key=c.account_key AND av.version=c.current_version JOIN pactwoven.financial_account_fences af ON af.account_key=c.account_key
   WHERE pa.account_key=d#>>'{account,key}' AND pa.environment=v->>'environment' AND pa.organization_id=v->>'organizationId' AND c.accepts_observations AND c.revoked_at IS NULL
   AND c.current_version=(d#>>'{account,version}')::int AND af.generation=(d#>>'{account,financialUseEpoch}')::int AND av.asset_key=d#>>'{asset,key}' AND pactwoven.finance_hash(to_jsonb(av))=d#>>'{account,recordHash}')
  THEN blockers:=blockers||'"ACCOUNT_CHANGED"'::jsonb;END IF;
  IF d->'governance'='null'::jsonb THEN blockers:=blockers||'"GOVERNANCE_MISSING"'::jsonb;ELSIF d->'governance' IS DISTINCT FROM pactwoven.financial_policy_control(d#>>'{governance,budgetAccountId}') THEN blockers:=blockers||'"GOVERNANCE_CHANGED"'::jsonb;END IF;
  BEGIN PERFORM pactwoven.financial_policy_documents(v->>'environment',v->>'organizationId',v->>'responsibilityId',d->'documents');EXCEPTION WHEN SQLSTATE 'FP002' THEN blockers:=blockers||'"DOCUMENT_CHANGED"'::jsonb;END;
  SELECT * INTO f FROM pactwoven.financial_authority_fences WHERE environment=v->>'environment' AND organization_id=v->>'organizationId' AND responsibility_id=v->>'responsibilityId';
  SELECT * INTO s FROM pactwoven.financial_site_fences WHERE environment=v->>'environment' AND organization_id=v->>'organizationId' AND site_id=d#>>'{scope,site,id}';
  IF d#>'{scope,authority}' IS DISTINCT FROM pactwoven.financial_authority_snapshot(f) OR d#>'{scope,site}' IS DISTINCT FROM jsonb_build_object('id',s.site_id,'generation',s.generation,'recordHash',s.record_hash)
   OR NOT coalesce(s.active,false) OR NOT EXISTS(SELECT 1 FROM pactwoven.organizations WHERE environment=v->>'environment' AND id=v->>'organizationId' AND authority_epoch=(v->>'organizationEpoch')::int)
  THEN blockers:=blockers||'"SCOPE_CHANGED"'::jsonb;END IF;
 END IF;
 RETURN jsonb_build_object('record',v,'reference',pactwoven.financial_policy_ref(v),'current',is_current,'state',state,'blockers',blockers,'effectiveAuthority',false);
END $$;
CREATE FUNCTION pactwoven.financial_policy_read(eid uuid,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c jsonb;v jsonb;BEGIN
 PERFORM pactwoven.financial_policy_require('read',q);c:=pactwoven.financial_policy_context(eid,q->>'environment',q->>'organizationId',q->>'responsibilityId','authorizer');
 SELECT body INTO v FROM pactwoven.financial_policy_records WHERE environment=q->>'environment' AND organization_id=q->>'organizationId' AND id=q->>'id'
  AND responsibility_id IS NOT DISTINCT FROM(q->>'responsibilityId') AND(q->'version'='null'::jsonb OR version=(q->>'version')::int) ORDER BY version DESC LIMIT 1;
 IF v IS NULL THEN RETURN NULL;END IF;RETURN pactwoven.financial_policy_projection(v);
END $$;
CREATE FUNCTION pactwoven.financial_policy_list(eid uuid,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c jsonb;v jsonb;items jsonb:='[]';last_id text;has_more boolean:=false;BEGIN
 PERFORM pactwoven.financial_policy_require('list',q);c:=pactwoven.financial_policy_context(eid,q->>'environment',q->>'organizationId',q->>'responsibilityId','authorizer');
 FOR v IN SELECT x.body FROM(SELECT DISTINCT ON(id) id,body FROM pactwoven.financial_policy_records WHERE environment=q->>'environment' AND organization_id=q->>'organizationId'
   AND responsibility_id=q->>'responsibilityId' AND kind='draft' AND(q->'afterId'='null'::jsonb OR id COLLATE "C">(q->>'afterId') COLLATE "C") ORDER BY id,version DESC)x ORDER BY x.id COLLATE "C" LIMIT(q->>'limit')::int+1 LOOP
  IF jsonb_array_length(items)=(q->>'limit')::int THEN has_more:=true;EXIT;END IF;
  items:=items||jsonb_build_array(pactwoven.financial_policy_projection(v));last_id:=v->>'id';
 END LOOP;
 RETURN jsonb_build_object('items',items,'nextId',CASE WHEN has_more THEN last_id ELSE NULL END);
END $$;
CREATE FUNCTION pactwoven.financial_policy_recover(eid uuid,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c jsonb;r jsonb;BEGIN
 PERFORM pactwoven.financial_policy_require('lookup',q);c:=pactwoven.financial_policy_context(eid,q->>'environment',q->>'organizationId',q->>'responsibilityId','authorizer');
 SELECT result INTO r FROM pactwoven.financial_policy_operations WHERE environment=q->>'environment' AND organization_id=q->>'organizationId' AND actor_id=c#>>'{identity,actor,actorId}'
  AND responsibility_id IS NOT DISTINCT FROM(q->>'responsibilityId') AND kind=q->>'kind' AND key=q->>'key';
 IF r IS NOT NULL AND r->>'commandHash' IS DISTINCT FROM q->>'commandHash' THEN RAISE EXCEPTION USING ERRCODE='FP005',MESSAGE='Original policy request differs';END IF;RETURN r;
END $$;
CREATE FUNCTION pactwoven.financial_policy_append_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE prior jsonb;account record;latest int;BEGIN
 IF TG_TABLE_NAME='financial_policy_principals' THEN
  PERFORM id FROM pactwoven.organizations WHERE environment=NEW.environment AND id=NEW.organization_id FOR UPDATE;
  SELECT to_jsonb(p) INTO prior FROM pactwoven.financial_policy_principals p WHERE principal_oid=NEW.principal_oid AND environment=NEW.environment AND organization_id=NEW.organization_id ORDER BY version DESC LIMIT 1;
  IF NEW.version<>coalesce((prior->>'version')::int,0)+1 OR(prior IS NOT NULL AND(to_jsonb(NEW)-ARRAY['version','active','expires_at']) IS DISTINCT FROM(prior-ARRAY['version','active','expires_at']))
   OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE oid=NEW.principal_oid AND rolname=NEW.principal_name AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
  THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Immutable contiguous private policy binding required';END IF;
 ELSIF TG_TABLE_NAME='financial_policy_records' THEN
  SELECT body INTO prior FROM pactwoven.financial_policy_records WHERE environment=NEW.environment AND organization_id=NEW.organization_id AND id=NEW.id ORDER BY version DESC LIMIT 1;
  IF NEW.version<>coalesce((prior->>'version')::int,0)+1 OR NEW.body->'predecessor' IS DISTINCT FROM coalesce(pactwoven.financial_policy_ref(prior),'null'::jsonb)
   OR(prior IS NOT NULL AND(NEW.kind<>prior->>'kind' OR(NEW.body->>'responsibilityId') IS DISTINCT FROM(prior->>'responsibilityId')))
  THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact contiguous policy record required';END IF;
  IF NEW.kind='document' AND prior IS NOT NULL AND(NEW.body->>'purpose'<>prior->>'purpose' OR NEW.body#>>'{actor,actorId}'<>prior#>>'{actor,actorId}') THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Original policy document identity required';END IF;
  IF NEW.kind='draft' AND((prior IS NULL AND NEW.body->>'state'<>'DRAFT') OR(prior IS NOT NULL AND(prior->>'state'<>'DRAFT'
   OR NEW.body#>>'{requester,actorId}'<>prior#>>'{requester,actorId}' OR NEW.body#>>'{requester,subject}'<>prior#>>'{requester,subject}'
   OR(NEW.body->>'state'='WITHDRAWN' AND NEW.body->'draft' IS DISTINCT FROM prior->'draft')))) THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Original policy draft transition required';END IF;
  IF NEW.kind='governance' AND((prior IS NULL AND NEW.body->>'state'<>'OPEN') OR(prior IS NOT NULL AND(prior->>'state'<>'OPEN'
   OR NEW.body#>>'{proposer,actorId}'<>prior#>>'{proposer,actorId}' OR NEW.body#>>'{proposer,subject}'<>prior#>>'{proposer,subject}'
   OR NEW.body#>>'{bundle,budgetAccountId}'<>prior#>>'{bundle,budgetAccountId}'
   OR(NEW.body->>'state'<>'OPEN' AND(NEW.body->'bundle' IS DISTINCT FROM prior->'bundle' OR NEW.body->'expectedControl' IS DISTINCT FROM prior->'expectedControl'
    OR NEW.body->'proposer' IS DISTINCT FROM prior->'proposer' OR NEW.body->'decisionNonce' IS DISTINCT FROM prior->'decisionNonce' OR NEW.body->'expiresAt' IS DISTINCT FROM prior->'expiresAt')))))
  THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Original governance proposal transition required';END IF;
 ELSIF TG_TABLE_NAME='financial_budget_periods' THEN
  IF EXISTS(SELECT 1 FROM pactwoven.financial_budget_periods WHERE budget_account_id=NEW.budget_account_id AND id<>NEW.id AND starts_at<NEW.ends_at AND ends_at>NEW.starts_at) THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Budget periods must be non-overlapping';END IF;
 ELSIF TG_TABLE_NAME='financial_governance_controls' THEN
  SELECT max(generation) INTO latest FROM pactwoven.financial_governance_controls WHERE budget_account_id=NEW.budget_account_id;
  IF NEW.generation<>coalesce(latest,0)+1 THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Contiguous governance controls required';END IF;
 END IF;RETURN NEW;
END $$;
CREATE FUNCTION pactwoven.financial_policy_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE oid uuid;op pactwoven.financial_policy_operations%ROWTYPE;r pactwoven.financial_policy_records%ROWTYPE;prior jsonb;v jsonb;expected_kind text;ctrl record;before_ctrl jsonb;ev jsonb;
BEGIN
 oid:=CASE WHEN TG_TABLE_NAME='financial_policy_operations' THEN(to_jsonb(NEW)->>'id')::uuid ELSE(to_jsonb(NEW)->>'operation_id')::uuid END;
 SELECT * INTO op FROM pactwoven.financial_policy_operations WHERE id=oid;
 SELECT * INTO r FROM pactwoven.financial_policy_records WHERE operation_id=oid;
 v:=op.command;expected_kind:=CASE op.kind WHEN 'save_document' THEN 'document' WHEN 'save_draft' THEN 'draft' WHEN 'withdraw_draft' THEN 'draft'
  WHEN 'propose_governance' THEN 'governance' WHEN 'accept_governance' THEN 'governance' WHEN 'reject_governance' THEN 'governance' END;
 IF op.id IS NULL OR r.id IS NULL OR expected_kind IS NULL OR r.kind<>expected_kind OR r.environment<>op.environment OR r.organization_id<>op.organization_id
  OR r.responsibility_id IS DISTINCT FROM op.responsibility_id OR r.body#>>'{actor,actorId}'<>op.actor_id OR r.body->>'operationId'<>oid::text
  OR op.command_hash IS DISTINCT FROM pactwoven.financial_policy_command_hash(op.actor_id,v) OR v->>'kind' IS DISTINCT FROM op.kind OR v->>'key' IS DISTINCT FROM op.key
  OR v->>'environment' IS DISTINCT FROM op.environment OR v->>'organizationId' IS DISTINCT FROM op.organization_id OR v->>'responsibilityId' IS DISTINCT FROM op.responsibility_id
  OR v->>'id' IS DISTINCT FROM r.id OR v->'previous' IS DISTINCT FROM r.body->'predecessor' OR v->'organizationEpoch' IS DISTINCT FROM r.body->'organizationEpoch'
  OR op.result IS DISTINCT FROM jsonb_build_object('schemaVersion',1,'id',op.id,'environment',op.environment,'organizationId',op.organization_id,'actorId',op.actor_id,'responsibilityId',op.responsibility_id,
   'kind',op.kind,'key',op.key,'commandHash',op.command_hash,'target',pactwoven.financial_policy_ref(r.body),'body',r.body,'financialState',NULL,'effectiveAuthority',false)
  OR NOT EXISTS(SELECT 1 FROM pactwoven.financial_policy_audit WHERE operation_id=oid AND body=op.result-'body')
  OR NOT EXISTS(SELECT 1 FROM pactwoven.financial_policy_outbox WHERE operation_id=oid AND body=op.result-'body') THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact reciprocal policy record operation audit and outbox required';END IF;
 PERFORM pactwoven.financial_policy_require('command',v);
 SELECT body INTO ev FROM pactwoven.financial_policy_evidence WHERE id=(r.body#>>'{identityEvidence,id}')::uuid;
 IF ev IS NULL OR ev->>'kind'<>'identity' OR ev->>'environment'<>r.environment OR ev->>'organizationId'<>r.organization_id OR ev->'actor' IS DISTINCT FROM r.body->'actor'
  OR r.body->'identityEvidence' IS DISTINCT FROM jsonb_build_object('id',ev->'id','version',1,'recordHash',pactwoven.financial_policy_hash('evidence',ev))
 THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact original policy identity observation required';END IF;
 IF r.version>1 THEN SELECT body INTO prior FROM pactwoven.financial_policy_records WHERE environment=r.environment AND organization_id=r.organization_id AND id=r.id AND version=r.version-1;
  IF prior IS NULL OR pactwoven.financial_policy_ref(prior) IS DISTINCT FROM r.body->'predecessor' THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact intermediate policy history required';END IF;
 END IF;
 IF op.kind='save_document' THEN
  IF r.body->'text' IS DISTINCT FROM v->'text' OR r.body->'purpose' IS DISTINCT FROM v->'purpose' THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact policy document command required';END IF;
 ELSIF op.kind='save_draft' THEN
  IF r.body->'draft' IS DISTINCT FROM v->'draft' OR r.body->>'state'<>'DRAFT' OR r.body->'requester' IS DISTINCT FROM r.body->'actor' THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact policy draft command required';END IF;
 ELSIF op.kind='withdraw_draft' THEN
  IF prior IS NULL OR r.body->>'state'<>'WITHDRAWN' OR r.body->'draft' IS DISTINCT FROM prior->'draft' OR r.body->'requester' IS DISTINCT FROM prior->'requester' THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact withdrawn draft required';END IF;
 ELSIF op.kind='propose_governance' THEN
  IF r.body->'bundle' IS DISTINCT FROM v->'bundle' OR r.body->'expectedControl' IS DISTINCT FROM v->'expectedControl' OR r.body->'expiresAt' IS DISTINCT FROM v->'expiresAt'
   OR r.body->>'state'<>'OPEN' OR r.body->'proposer' IS DISTINCT FROM r.body->'actor' THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact governance proposal command required';END IF;
  IF NOT EXISTS(SELECT 1 FROM pactwoven.financial_budget_accounts WHERE id=r.body#>>'{bundle,budgetAccountId}' AND environment=r.environment AND organization_id=r.organization_id AND asset_key=r.body#>>'{bundle,asset,key}')
   OR NOT EXISTS(SELECT 1 FROM pactwoven.financial_budget_periods WHERE id=r.body#>>'{bundle,period,id}' AND budget_account_id=r.body#>>'{bundle,budgetAccountId}'
    AND starts_at=(r.body#>>'{bundle,period,startsAt}')::timestamptz AND ends_at=(r.body#>>'{bundle,period,endsAt}')::timestamptz) THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Stable budget and fixed period required';END IF;
 ELSE
  IF prior IS NULL OR r.body->>'state'<>(CASE op.kind WHEN 'accept_governance' THEN 'ACCEPTED' ELSE 'REJECTED' END)
   OR r.body->'expectedControl' IS DISTINCT FROM v->'expectedControl' OR r.body#>>'{decision,proposerObservation,id}' IS DISTINCT FROM v->>'proposerEvidenceId'
  THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact governance decision command required';END IF;
  SELECT body INTO ev FROM pactwoven.financial_policy_evidence WHERE id=(v->>'proposerEvidenceId')::uuid;
  IF ev IS NULL OR ev->'actor' IS DISTINCT FROM r.body->'proposer' OR r.body#>'{decision,proposerObservation}' IS DISTINCT FROM jsonb_build_object('id',ev->'id','version',1,'recordHash',pactwoven.financial_policy_hash('evidence',ev)) THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact proposer observation required';END IF;
  SELECT body INTO ev FROM pactwoven.financial_policy_evidence WHERE id=(r.body#>>'{decision,approverObservation,id}')::uuid;
  IF ev IS NULL OR ev->'actor' IS DISTINCT FROM r.body->'actor' OR r.body#>'{decision,approverObservation}' IS DISTINCT FROM jsonb_build_object('id',ev->'id','version',1,'recordHash',pactwoven.financial_policy_hash('evidence',ev)) THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact approver observation required';END IF;
 END IF;
 IF op.kind='accept_governance' THEN
  SELECT * INTO ctrl FROM pactwoven.financial_governance_controls WHERE operation_id=oid;
  IF ctrl.operation_id IS NULL OR ctrl.budget_account_id<>r.body#>>'{bundle,budgetAccountId}' OR ctrl.environment<>r.environment OR ctrl.organization_id<>r.organization_id
   OR ctrl.record_id<>r.id OR ctrl.record_version<>r.version OR ctrl.record_hash<>r.hash OR v->>'nonce' IS DISTINCT FROM r.body->>'decisionNonce'
  THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact consent configuration history required';END IF;
  SELECT jsonb_build_object('budgetAccountId',budget_account_id,'generation',generation,'accepted',jsonb_build_object('id',record_id,'version',record_version,'recordHash',record_hash)) INTO before_ctrl
   FROM pactwoven.financial_governance_controls WHERE budget_account_id=ctrl.budget_account_id AND generation=ctrl.generation-1;
  IF ctrl.generation=1 THEN before_ctrl:=jsonb_build_object('budgetAccountId',ctrl.budget_account_id,'generation',0,'accepted',NULL);END IF;
  IF before_ctrl IS NULL OR before_ctrl IS DISTINCT FROM r.body->'expectedControl' THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact prior governance configuration required';END IF;
  SELECT body INTO ev FROM pactwoven.financial_policy_evidence WHERE id=(v->>'mfaEvidenceId')::uuid;
  IF ev IS NULL OR ev->>'kind'<>'mfa' OR ev->'intent' IS DISTINCT FROM pactwoven.financial_policy_intent(prior,r.body->'actor',op.key,(r.body->>'organizationEpoch')::int)
   OR r.body#>'{decision,mfaEvidence}' IS DISTINCT FROM jsonb_build_object('id',ev->'id','version',1,'recordHash',pactwoven.financial_policy_hash('evidence',ev))
   OR r.body#>'{decision,intentHash}' IS DISTINCT FROM ev->'intentHash' OR r.body#>'{decision,requestHash}' IS DISTINCT FROM ev->'requestHash'
   OR NOT EXISTS(SELECT 1 FROM pactwoven.financial_policy_evidence_uses WHERE operation_id=oid AND evidence_id=(ev->>'id')::uuid)
  THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Exact consumed policy MFA required';END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM pactwoven.financial_governance_controls WHERE operation_id=oid) OR EXISTS(SELECT 1 FROM pactwoven.financial_policy_evidence_uses WHERE operation_id=oid) THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Only independent governance acceptance records configuration consent';END IF;
 END IF;
 IF TG_TABLE_NAME='financial_budget_accounts' AND(op.kind<>'propose_governance' OR to_jsonb(NEW)->>'id'<>r.body#>>'{bundle,budgetAccountId}') THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Budget identity requires original proposal';END IF;
 IF TG_TABLE_NAME='financial_budget_periods' AND(op.kind<>'propose_governance' OR to_jsonb(NEW)->>'id'<>r.body#>>'{bundle,period,id}') THEN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Budget period requires original proposal';END IF;
 RETURN NULL;
END $$;
CREATE FUNCTION pactwoven.financial_policy_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION USING ERRCODE='FP007',MESSAGE='Policy records, bindings, periods and configuration history are immutable';END $$;
DO $$ DECLARE item text;routine regprocedure;BEGIN
 FOREACH item IN ARRAY ARRAY['financial_policy_principals','financial_policy_evidence','financial_policy_records','financial_policy_operations','financial_policy_audit','financial_policy_outbox',
  'financial_policy_evidence_uses','financial_budget_accounts','financial_budget_periods','financial_governance_controls'] LOOP
  EXECUTE format('ALTER TABLE pactwoven.%I ENABLE ROW LEVEL SECURITY',item);
  EXECUTE format('REVOKE ALL ON pactwoven.%I FROM PUBLIC,pactwoven_runtime,pactwoven_provisioner,pactwoven_access_provisioner,pactwoven_mandate_writer,pactwoven_finance_observer,pactwoven_custody_setup_writer,pactwoven_custody_setup_verifier,pactwoven_financial_verifier,pactwoven_financial_authorizer',item);
  EXECUTE format('CREATE TRIGGER financial_policy_no_mutation BEFORE UPDATE OR DELETE ON pactwoven.%I FOR EACH ROW EXECUTE FUNCTION pactwoven.financial_policy_immutable()',item);
  EXECUTE format('CREATE TRIGGER financial_policy_no_truncate BEFORE TRUNCATE ON pactwoven.%I FOR EACH STATEMENT EXECUTE FUNCTION pactwoven.financial_policy_immutable()',item);
  IF item IN('financial_policy_principals','financial_policy_records','financial_budget_periods','financial_governance_controls') THEN EXECUTE format('CREATE TRIGGER financial_policy_append BEFORE INSERT ON pactwoven.%I FOR EACH ROW EXECUTE FUNCTION pactwoven.financial_policy_append_guard()',item);END IF;
  IF item NOT IN('financial_policy_principals','financial_policy_evidence') THEN EXECUTE format('CREATE CONSTRAINT TRIGGER financial_policy_complete AFTER INSERT ON pactwoven.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pactwoven.financial_policy_complete()',item);END IF;
 END LOOP;
 FOR routine IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='pactwoven'
  AND(p.proname LIKE 'financial_policy_%' OR p.proname IN('financial_budget_account_id','financial_budget_period_id')) LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,pactwoven_runtime,pactwoven_provisioner,pactwoven_access_provisioner,pactwoven_mandate_writer,pactwoven_finance_observer,pactwoven_custody_setup_writer,pactwoven_custody_setup_verifier,pactwoven_financial_verifier,pactwoven_financial_authorizer',routine);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION pactwoven.financial_policy_attest(jsonb) TO pactwoven_financial_verifier;
GRANT EXECUTE ON FUNCTION pactwoven.financial_policy_command(uuid,jsonb),pactwoven.financial_policy_read(uuid,jsonb),pactwoven.financial_policy_list(uuid,jsonb),pactwoven.financial_policy_recover(uuid,jsonb) TO pactwoven_financial_authorizer;
COMMIT;
